// Synthetic September 2026 journal entries for a fictional 5-entity group ("Kestrel Group").
// Production: replace this node with an HTTP Request to your ERP's journal-entries endpoint.
// _evalLabel = the issue planted in each entry; used only to score detection (eval), never by the checks.
const U={ctrl:'Priya Shah',cfo:'Tom Becker',acc1:'Ana Silva',acc2:'Marek Nowak',ops:'Chloe Martin',tax:'Daniel Okafor'};
const role={[U.ctrl]:'Controller',[U.cfo]:'CFO',[U.acc1]:'Accountant',[U.acc2]:'Accountant',[U.ops]:'Finance ops',[U.tax]:'Head of tax'};
const E={UK:'GBP',DE:'EUR',US:'USD',PL:'PLN',IE:'EUR'};
let rows=[];let n=0;
function je(ent,date,amt,desc,cb,ab,src,planted=[],created=null){n++;
 rows.push({id:'je_'+String(n).padStart(3,'0'),entryNumber:'JE-2026-'+String(900+n),entity:ent,currency:E[ent],
  postingDate:date,createdAt:(created||date)+'T10:15:00Z',amount:amt,description:desc,source:src,
  createdBy:cb,approvedBy:ab,approverRole:ab?role[ab]:null,_evalLabel:planted});}
// clean entries (approval level correct for the amount)
je('UK','2026-09-30',4200,'Accrual: September consultancy fees',U.acc1,null,'manual');
je('DE','2026-09-30',38450,'Accrual: September cloud hosting',U.acc1,U.ctrl,'manual');
je('US','2026-09-30',7380,'Accrual: US payroll taxes September',U.acc2,null,'manual');
je('IE','2026-09-30',2915,'Prepaid insurance release September',U.acc2,null,'manual');
je('PL','2026-09-29',21640,'Bank fee reclass',U.ops,null,'manual');
je('UK','2026-09-29',9870,'Accrual: contractor invoices September',U.acc1,null,'manual');
je('DE','2026-09-25',12735,'Depreciation September',U.acc1,null,'manual');
je('US','2026-09-30',54300,'Deferred revenue release September (US)',U.acc2,U.ctrl,'manual');
je('IE','2026-09-30',18260,'Accrual: office rent',U.acc2,U.ctrl,'manual');
je('DE','2026-09-30',412880,'Subscription revenue September (group)',U.acc1,U.cfo,'upload');
je('UK','2026-09-24',6145,'Reclass marketing to R&D',U.acc2,null,'manual');
je('US','2026-09-23',3912,'Card spend reclass travel',U.ops,null,'manual');
je('DE','2026-09-30',96410,'Intercompany recharge DE to US',U.acc1,U.ctrl,'manual');
je('US','2026-09-30',104795,'Intercompany recharge DE to US (US side)',U.acc2,U.ctrl,'manual');
je('IE','2026-09-22',840,'FX rounding difference',U.ops,null,'manual');
je('PL','2026-09-30',31550,'Payroll accrual PL',U.acc2,null,'manual');
je('DE','2026-09-30',13980,'VAT reclass Q3',U.tax,null,'manual');
je('UK','2026-09-21',11265,'Accrual: legal fees',U.acc1,null,'manual');
je('US','2026-09-30',168400,'Sales tax liability true-up',U.tax,U.cfo,'manual');
je('DE','2026-09-30',14350,'Bonus accrual September',U.acc1,null,'manual');
je('IE','2026-09-30',5630,'Deferred revenue release September (IE)',U.acc2,null,'manual');
// planted: above threshold, no approval recorded (bulk uploads bypassing approval)
je('DE','2026-09-30',87215,'Revenue adjustment upload - September',U.acc2,null,'upload',['no_approval']);
je('US','2026-09-30',23940,'Card revenue US September',U.acc2,null,'upload',['no_approval']);
je('UK','2026-09-30',146380,'Revenue reclass UK - bulk upload',U.ops,null,'upload',['no_approval']);
je('UK','2026-09-30',14730,'Accrual: audit fee UK',U.acc1,null,'manual',['no_approval']);
// planted: approved below the required level (needs CFO)
je('DE','2026-09-30',238600,'Year-to-date bonus true-up',U.acc1,U.ctrl,'manual',['approver_too_junior']);
je('US','2026-09-30',176250,'Customer credit write-off',U.acc2,U.ctrl,'manual',['approver_too_junior']);
// planted: self-approved (segregation of duties)
je('IE','2026-09-30',42300,'Accrual: consulting project',U.ctrl,U.ctrl,'manual',['self_approved']);
je('PL','2026-09-30',88400,'Reclass software costs',U.acc1,U.acc1,'manual',['self_approved','approver_too_junior']);
// planted: posted into a closed period
je('DE','2026-08-31',7860,'Missed August accrual - telecoms',U.acc1,null,'manual',['closed_period'],'2026-09-17');
// planted: weekend entry and round amounts
je('UK','2026-09-25',2375,'Reclass entertainment',U.ops,null,'manual',['weekend'],'2026-09-26');
je('DE','2026-09-30',9000,'Accrual: misc provision',U.acc2,null,'manual',['weekend','round_amount'],'2026-09-27');
je('US','2026-09-30',12000,'Provision: general',U.acc2,null,'manual',['round_amount']);
// edge case: just under the Controller threshold after FX (PLN 65,100 x 0.23 = EUR 14,973) -> clean
je('PL','2026-09-30',65100,'Accrual: marketing agency',U.acc2,null,'manual');
return rows.map(r=>({json:r}));

// Deterministic policy engine. Claude never makes these decisions.
const POLICY={version:'JE-APPROVAL-v0.1 (example policy - confirm thresholds with the controller)',
  controllerFromEUR:15000, cfoFromEUR:150000,
  fxToEUR:{EUR:1,GBP:1.16,USD:0.92,PLN:0.23}, fxRateDate:'2026-09-30',
  closedThrough:'2026-08-31', roundMinEUR:5000, roundStep:1000};
const rank={'Controller':1,'CFO':2};
const fmt=x=>Math.round(x).toLocaleString('en');
function check(j){
  const rate=POLICY.fxToEUR[j.currency];
  const f=[];
  if(rate===undefined) return {...j,amountEUR:null,requiredApproval:null,findings:[{code:'unknown_currency',severity:'high',detail:'No policy FX rate for '+j.currency}],result:'exception',policyVersion:POLICY.version,checkedAt:new Date().toISOString()};
  const eur=Math.round(j.amount*rate);
  const req=eur>=POLICY.cfoFromEUR?'CFO':eur>=POLICY.controllerFromEUR?'Controller':'None';
  if(req!=='None'&&!j.approvedBy) f.push({code:'no_approval',severity:'high',detail:'EUR '+fmt(eur)+' needs '+req+' approval; none recorded'});
  if(req!=='None'&&j.approvedBy&&(rank[j.approverRole]||0)<rank[req]) f.push({code:'approver_too_junior',severity:'high',detail:'Needs '+req+'; approved by '+j.approverRole});
  if(j.approvedBy&&j.approvedBy===j.createdBy) f.push({code:'self_approved',severity:'high',detail:'Created and approved by '+j.createdBy});
  if(j.postingDate<=POLICY.closedThrough&&j.createdAt.slice(0,10)>POLICY.closedThrough) f.push({code:'closed_period',severity:'high',detail:'Posted to '+j.postingDate+' (closed) on '+j.createdAt.slice(0,10)});
  const d=new Date(j.createdAt).getUTCDay(); // the day a person entered it, not the accounting date
  if(d===0||d===6) f.push({code:'weekend',severity:'review',detail:'Entered on a '+(d===0?'Sunday':'Saturday')+' ('+j.createdAt.slice(0,10)+')'});
  if(eur>=POLICY.roundMinEUR&&j.amount%POLICY.roundStep===0) f.push({code:'round_amount',severity:'review',detail:'Round amount '+j.currency+' '+fmt(j.amount)});
  const result=f.some(x=>x.severity==='high')?'exception':f.length?'review':'pass';
  return {...j,amountEUR:eur,fxRate:rate,requiredApproval:req,findings:f,result,policyVersion:POLICY.version,checkedAt:new Date().toISOString()};
}
return $input.all().map(i=>({json:check(i.json)}));

// Validate Claude's JSON. Any failure -> entry is still logged and sent to manual review. Never dropped.
const out=[];
const replies=$input.all();
const fence=String.fromCharCode(96).repeat(3);
for(let i=0;i<replies.length;i++){
  const orig=$('Policy checks').itemMatching(i).json;
  const r=replies[i].json;
  let exp;
  try{
    if(r.error) throw new Error('API error: '+JSON.stringify(r.error).slice(0,200));
    const txt=(r.content||[]).filter(c=>c.type==='text').map(c=>c.text).join('').split(fence+'json').join('').split(fence).join('').trim();
    const p=JSON.parse(txt);
    for(const k of ['summary','risk','next_step','confidence']) if(!p[k]) throw new Error('missing '+k);
    if(!['high','medium','low'].includes(p.confidence)) throw new Error('bad confidence');
    exp={...p, model:r.model||null, ok:true};
  }catch(e){
    exp={summary:'Explanation unavailable - review manually',risk:'',next_step:'Controller to review findings directly',confidence:'low',ok:false,error:String(e.message).slice(0,300)};
  }
  out.push({json:{...orig, explanation:exp}});
}
return out;

// One audit-log row per entry, pass or fail.
// Unique key (run_month, entry_number, policy_version) in Supabase: a rerun of the same month under the
// same policy is rejected row by row (first write wins, history is never overwritten); a rerun under a
// new policy version is logged as new rows.
const runMonth='2026-09';
return $input.all().map(i=>{const j=i.json;return {json:{
 run_month:runMonth, entry_number:j.entryNumber, entity:j.entity, currency:j.currency, amount:j.amount,
 amount_eur:j.amountEUR, fx_rate:j.fxRate, required_approval:j.requiredApproval, created_by:j.createdBy,
 approved_by:j.approvedBy, approver_role:j.approverRole, source:j.source, description:j.description,
 result:j.result, findings:j.findings, explanation:j.explanation, policy_version:j.policyVersion,
 checked_at:j.checkedAt, eval_label:j._evalLabel}};});

// Monthly control report: what was checked, what passed, what was flagged. Runs once over all entries.
const rows=$('Shape log row').all().map(i=>i.json);
const logged=$('Audit log (Supabase)').all();
const logFail=logged.filter(i=>i.json&&i.json.error).length;
const esc=s=>String(s==null?'':s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
const fmt=n=>n==null?'':Math.round(n).toLocaleString('en');
const by=r=>rows.filter(x=>x.result===r);
const ex=by('exception'),rv=by('review'),ps=by('pass');
const evalOk=rows.filter(r=>r.findings.map(f=>f.code).sort().join()===[...(r.eval_label||[])].sort().join()).length;
const llmN=rows.filter(r=>r.explanation).length, llmOk=rows.filter(r=>r.explanation&&r.explanation.ok).length;
const exEUR=ex.reduce((a,r)=>a+(r.amount_eur||0),0);
const codes={};rows.forEach(r=>r.findings.forEach(f=>codes[f.code]=(codes[f.code]||0)+1));
const label={no_approval:'Above threshold, no approval',approver_too_junior:'Approved below required level',self_approved:'Self-approved (segregation of duties)',closed_period:'Posted into a closed period',weekend:'Entered at the weekend',round_amount:'Round amount'};
const tr=r=>'<tr class="'+r.result+'"><td>'+esc(r.entry_number)+'<br><span class="m">'+esc(r.entity)+', '+esc(r.source)+'</span></td>'+
 '<td>'+esc(r.description)+'<br><span class="m">'+esc(r.currency)+' '+fmt(r.amount)+' = EUR '+fmt(r.amount_eur)+'</span></td>'+
 '<td>'+esc(r.created_by)+'<br><span class="m">approved: '+esc(r.approved_by||'none')+(r.approver_role?' ('+esc(r.approver_role)+')':'')+'; needs '+esc(r.required_approval)+'</span></td>'+
 '<td>'+r.findings.map(f=>'<div><b>'+esc(label[f.code]||f.code)+'</b><br><span class="m">'+esc(f.detail)+'</span></div>').join('')+'</td>'+
 '<td>'+(r.explanation?'<div>'+esc(r.explanation.summary)+'</div><div class="m">Risk: '+esc(r.explanation.risk)+'</div><div class="m"><b>Next:</b> '+esc(r.explanation.next_step)+'</div>':'')+'</td></tr>';
const head='<tr><th>Entry</th><th>What</th><th>Who</th><th>Policy finding</th><th>Explanation (Claude)</th></tr>';
const css='body{font:15px/1.5 system-ui,sans-serif;color:#1F2A33;background:#FBFCFC;margin:0}main{max-width:1100px;margin:0 auto;padding:40px 20px}h1{font:600 1.8rem Georgia,serif;margin:0 0 6px}h2{font:600 1.25rem Georgia,serif;margin:36px 0 10px}.m{color:#5F6B74;font-size:.85em}.k{display:flex;gap:28px;flex-wrap:wrap;margin:20px 0}.k div{min-width:120px}.k b{display:block;font:600 1.8rem Georgia,serif}.sc{overflow-x:auto}table{border-collapse:collapse;width:100%;min-width:860px;font-size:.9rem}th,td{text-align:left;vertical-align:top;padding:9px 10px 9px 0;border-bottom:1px solid #D8DEE3}th{color:#5F6B74;font-size:.8rem}tr.exception td:first-child{border-left:3px solid #B3261E;padding-left:8px}tr.review td:first-child{border-left:3px solid #A8661A;padding-left:8px}ul{padding-left:18px}';
const html='<!DOCTYPE html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>JE control report September 2026</title><style>'+css+'</style></head><body><main>'+
 '<h1>Journal entry control report: September 2026</h1>'+
 '<p class="m">Kestrel Group (fictional), 5 entities. Policy '+esc(rows[0]&&rows[0].policy_version)+'. Thresholds tested in EUR at fixed 30 Sep rates. Generated '+new Date().toISOString().slice(0,16).replace('T',' ')+' UTC. Read-only: this monitor detects, it does not block or change entries.</p>'+
 '<div class="k"><div><b>'+rows.length+'</b><span class="m">entries checked</span></div><div><b>'+ps.length+'</b><span class="m">passed</span></div><div><b style="color:#B3261E">'+ex.length+'</b><span class="m">policy exceptions</span></div><div><b style="color:#A8661A">'+rv.length+'</b><span class="m">flagged for review</span></div><div><b>EUR '+(exEUR/1e6).toFixed(2)+'m</b><span class="m">value in exceptions</span></div></div>'+
 '<h2>What was checked</h2><ul>'+Object.keys(label).map(c=>'<li>'+label[c]+': <b>'+(codes[c]||0)+'</b></li>').join('')+'</ul>'+
 '<h2>Exception queue (controller action)</h2><div class="sc"><table>'+head+ex.map(tr).join('')+'</table></div>'+
 '<h2>For review (not breaches)</h2><div class="sc"><table>'+head+rv.map(tr).join('')+'</table></div>'+
 '<h2>Run quality</h2><ul><li>Detection eval: <b>'+evalOk+'/'+rows.length+'</b> entries match the labelled test set.</li><li>Explanations: <b>'+llmOk+'/'+llmN+'</b> valid JSON from Claude; failures fall back to manual review and are still logged.</li><li>Audit log: <b>'+(rows.length-logFail)+'/'+rows.length+'</b> rows written to je_control_log'+(logFail?' ('+logFail+' rejected, e.g. duplicates from a rerun of the same month and policy version)':'')+'. Each row carries the policy version and FX rate, so an auditor can re-perform the check.</li></ul>'+
 '</main></body></html>';
return [{json:{checked:rows.length,passed:ps.length,exceptions:ex.length,review:rv.length,exceptionValueEUR:exEUR,evalMatch:evalOk+'/'+rows.length,explanationsValid:llmOk+'/'+llmN,auditLogWritten:(rows.length-logFail)+'/'+rows.length}, binary:{report:{data:Buffer.from(html).toString('base64'),mimeType:'text/html',fileName:'je_control_report_2026-09.html'}}}];
